// Butonla LED: her basışta LED'in durumu değişir.
const int BUTON_PIN = 2;   // butonun öbür ucu GND'de; iç pull-up açık
const int LED_PIN = 9;
const unsigned long TITRESIM_MS = 50;  // buton sıçramasını yok sayma süresi

bool ledAcik = false;
int oncekiOkuma = HIGH;
unsigned long sonDegisim = 0;

void setup() {
  Serial.begin(9600);
  pinMode(BUTON_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int okuma = digitalRead(BUTON_PIN);
  if (okuma != oncekiOkuma && millis() - sonDegisim > TITRESIM_MS) {
    sonDegisim = millis();
    if (okuma == LOW) {            // basıldı
      ledAcik = !ledAcik;
      digitalWrite(LED_PIN, ledAcik ? HIGH : LOW);
      Serial.println(ledAcik ? "LED acik" : "LED kapali");
    }
    oncekiOkuma = okuma;
  }
}
